style.css:
body {
  margin: 0;
  overflow: hidden;
  background-image: url("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRk9v57hUDYs1eE-iz3tJFlwuZxT4Ol4Liyfg&s");
  background-size: cover; /* or contain, depending on how you want it to fit */
  background-repeat: no-repeat;
  background-position: center; /* or other position values like top, bottom, left, right */
}

/* Optional: Add a semi-transparent overlay if the image is too bright */
body::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.2); /* Adjust the alpha value (0.2) for transparency */
  z-index: -1; /* Place overlay behind content */
}

/* Optional: If you want to use the gradient as an overlay */
body::before { /* Reusing the::before pseudo-element */
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(to right, #1a2a6c, #b21f1f, #fdbb2d); /* Example gradient */
    opacity: 0.3; /* Adjust opacity as needed */
    z-index: -1;
}
